        },
      })] : []),
    ],
    build: {
      outDir: "dist/web",
      emptyOutDir: true,
      sourcemap: uploadSourceMaps ? "hidden" : false,
    },
    server: {
      host: "127.0.0.1",
      port: 5173,
      proxy: {
        "/api": `http://127.0.0.1:${env.UB_PORT || "4200"}`,
      },
    },
  };
});

