import { randomUUID } from "node:crypto";
import { writeFileSync } from "node:fs";

const base = process.env.UB_BASE ?? "http://127.0.0.1:4310";
const session = await (await fetch(`${base}/api/session`)).json();
const token = session.token;
const out = "/tmp/opencode/e2e";

async function get(path) {
  const response = await fetch(`${base}/api/${path}`, { headers: { "x-ub-session-token": token } });
  return { status: response.status, body: await response.json() };
}

async function post(path, body) {
  const response = await fetch(`${base}/api/${path}`, {
    method: "POST",
    headers: { "content-type": "application/json", "x-ub-session-token": token },
    body: JSON.stringify(body),
  });
  return { status: response.status, body: await response.json().catch(() => null) };
}

const save = (name, value) => writeFileSync(`${out}/${name}.json`, `${JSON.stringify(value, null, 2)}\n`);
const projectOf = (body) => body?.project ?? body;

const start = await get("project");
save("01-project-start", start);

const source = await post("project/source", {
  actionId: randomUUID(),
  expectedRevision: projectOf(start.body).revision,
  kind: "NEW_PROJECT",
  label: "Ghost story from sensor logs (live test)",
});
save("02-source", source);
if (source.status >= 300) throw new Error(`source failed: ${source.status}`);

const afterSource = projectOf(source.body);
const engine = await post("engine/selection", {
  actionId: randomUUID(),
  expectedRevision: afterSource.revision,
  providerID: "opencode-go",
  id: "deepseek-v4.1-flash",
  variant: "high",
  acceptPaidOrUnknown: true,
});
save("03-engine-selection", engine);
if (engine.status >= 300) throw new Error(`engine selection failed: ${engine.status} ${JSON.stringify(engine.body).slice(0, 300)}`);

const afterEngine = projectOf(engine.body);
const question = "I want a small ghost-story generator built from my smart home sensor logs. In two sentences, what is the one question you should ask me first?";
const sentAt = new Date();
const message = await post("messages", {
  actionId: randomUUID(),
  expectedRevision: afterEngine.revision,
  intent: "clarify",
  text: question,
});
save("04-message-accepted", message);
if (message.status >= 300) throw new Error(`message failed: ${message.status} ${JSON.stringify(message.body).slice(0, 300)}`);

let reply = null;
let final = null;
for (let attempt = 0; attempt < 60; attempt += 1) {
  await new Promise((resolve) => setTimeout(resolve, 5000));
  const current = await get("project");
  final = current;
  const entries = projectOf(current.body).transcript ?? [];
  const oracle = entries.filter((entry) => entry.spirit === "oracle");
  if (oracle.length > 0) {
    reply = oracle[oracle.length - 1];
    break;
  }
}
save("05-project-after-reply", final);

const repliedAt = new Date();
const seconds = ((repliedAt - sentAt) / 1000).toFixed(1);
console.log(JSON.stringify({
  sentAt: sentAt.toISOString(),
  repliedAt: reply ? repliedAt.toISOString() : null,
  secondsToReply: reply ? Number(seconds) : null,
  model: "opencode-go/deepseek-v4.1-flash (variant high)",
  replyText: reply ? reply.text : null,
}, null, 2));

