import { randomUUID } from "node:crypto";
import { writeFileSync } from "node:fs";

const base = "https://unfinished-business.onrender.com";
const user = process.env.UB_ACCESS_USERNAME ?? "unfinished-business";
const password = process.env.UB_ACCESS_PASSWORD;
if (!password) {
  console.error("Set UB_ACCESS_PASSWORD in your shell (it is read from the environment and never printed).");
  process.exit(1);
}

const basic = `Basic ${Buffer.from(`${user}:${password}`).toString("base64")}`;
const out = "/tmp/opencode/e2e";
const save = (name, value) => writeFileSync(`${out}/live-${name}.json`, `${JSON.stringify(value, null, 2)}\n`);
const projectOf = (body) => body?.project ?? body;

const sessionResponse = await fetch(`${base}/api/session`, { headers: { authorization: basic } });
if (!sessionResponse.ok) throw new Error(`session failed: ${sessionResponse.status}`);
const token = (await sessionResponse.json()).token;

async function get(path) {
  const response = await fetch(`${base}/api/${path}`, { headers: { authorization: basic, "x-ub-session-token": token } });
  return { status: response.status, body: await response.json() };
}
async function post(path, body) {
  const response = await fetch(`${base}/api/${path}`, {
    method: "POST",
    headers: { authorization: basic, "content-type": "application/json", "x-ub-session-token": token },
    body: JSON.stringify(body),
  });
  return { status: response.status, body: await response.json().catch(() => null) };
}

const connection = await get("connection");
save("connection", connection.body);
const model = (connection.body.discovery?.models ?? []).find((entry) => entry.key === "opencode-go/deepseek-v4.1-flash");
console.log(JSON.stringify({
  state: connection.body.state,
  serverVersion: connection.body.serverVersion,
  modelAvailable: Boolean(model),
  pricing: model?.pricing ?? null,
}));

if (!model) {
  console.error("DeepSeek is not listed on the live instance; stopping before a model call.");
  process.exit(2);
}

const start = await get("project");
const current = projectOf(start.body);
let revision = current.revision;
if (current.source?.kind === "UNSELECTED") {
  const source = await post("project/source", {
    actionId: randomUUID(),
    expectedRevision: revision,
    kind: "NEW_PROJECT",
    label: "Ghost story from sensor logs (live instance test)",
  });
  save("source", source.body);
  revision = projectOf(source.body).revision;
}

const engine = await post("engine/selection", {
  actionId: randomUUID(),
  expectedRevision: revision,
  providerID: "opencode-go",
  id: "deepseek-v4.1-flash",
  variant: "high",
  acceptPaidOrUnknown: true,
});
save("engine", engine.body);
if (engine.status >= 300) throw new Error(`engine selection failed: ${engine.status}`);

const sentAt = new Date();
const message = await post("messages", {
  actionId: randomUUID(),
  expectedRevision: projectOf(engine.body).revision,
  intent: "clarify",
  text: "One sentence only: what is the first question you would ask someone building a ghost-story generator from their smart home sensor logs?",
});
save("message", message.body);
if (message.status >= 300) throw new Error(`message failed: ${message.status} ${JSON.stringify(message.body).slice(0, 200)}`);

let reply = null;
let before = [];
const initial = await get("project");
before = (projectOf(initial.body).transcript ?? []).filter((entry) => entry.spirit === "oracle").length;

for (let attempt = 0; attempt < 60; attempt += 1) {
  await new Promise((resolve) => setTimeout(resolve, 5000));
  const currentProject = await get("project");
  const oracle = (projectOf(currentProject.body).transcript ?? []).filter((entry) => entry.spirit === "oracle");
  if (oracle.length > before) {
    reply = oracle[oracle.length - 1];
    save("project-after-reply", currentProject.body);
    break;
  }
}

const repliedAt = new Date();
console.log(JSON.stringify({
  sentAt: sentAt.toISOString(),
  repliedAt: reply ? repliedAt.toISOString() : null,
  secondsToReply: reply ? Number(((repliedAt - sentAt) / 1000).toFixed(1)) : null,
  replyText: reply?.text ?? null,
  evidence: `${out}/live-project-after-reply.json`,
}, null, 2));

